type LineCreationMode = 'arrow' | 'line'
type PPTFlipAxis = 'horizontal' | 'vertical'
type PPTFreeformTool = 'highlight' | 'marker' | 'pen'
type PPTCreationTool =
  | {
      kind: 'shape'
      shape: PPTShapeKind
    }
  | {
      kind: 'text'
    }
  | {
      kind: 'sticky'
    }
  | {
      kind: 'section'
    }
  | {
      kind: 'comment'
    }
