  async function importPPTDeckPPTXFile(file: File) {
    const result = await importPPTDeckFromPPTXBlob(file)

    if (!result) {
      return false
    }

    return pastePPTDeckPPTXSource({
      ...result,
      fileName: file.name,
      fileSize: file.size,
    })
  }

  async function openPPTDeckPPTXFile(file: File) {
    setPPTXOpenStatus({
      fileName: file.name,
      kind: 'loading',
    })

    const result = await importPPTDeckFromPPTXBlob(file)

    if (!result) {
      setPPTXOpenStatus({
        fileName: file.name,
        kind: 'error',
      })
      return false
    }

    const source = {
      ...result,
      fileName: file.name,
      fileSize: file.size,
    }

    if (!replacePPTDeckPPTXSource(source)) {
      setPPTXOpenStatus({
        fileName: file.name,
        kind: 'error',
      })
      return false
    }

    setPPTXOpenStatus({
      fileName: file.name,
      format: result.format,
      kind: 'success',
      slideCount: result.deck.slides.length,
    })
    requestAnimationFrame(() => {
      fitPPTCanvasViewportToBounds({
        bounds: {
          h: result.deck.size.h,
          w: result.deck.size.w,
          x: 0,
          y: 0,
        },
        setViewport,
        stageElement: canvasStageElement,
      })
    })

    return true
  }

  function replacePPTDeckPPTXSource(source: PPTDeckPPTXImportSource) {
    const firstSlide = source.deck.slides[0]

    if (!firstSlide) {
      return false
    }

    commitDeck(() => {
      setLastDeckPPTXImportEffect(createPPTDeckPPTXImportEffect({
        importedSlides: source.deck.slides,
        mode: 'replace',
        source,
      }))
      selectSlide(firstSlide.id)

      return source.deck
    })

    return true
  }

  function pastePPTDeckPPTXSource(source: PPTDeckPPTXImportSource) {
    if (source.deck.slides.length === 0) {
      return false
    }

    commitDeck((current) => {
      const targetSlideId = current.slides.some((slide) =>
        slide.id === activeSlide.id)
        ? activeSlide.id
        : current.slides.at(-1)?.id

      if (!targetSlideId) {
        return current
      }

      const importedSlides = clonePPTDeckSlidesForImport(
        current,
        source.deck.slides,
      )

      if (importedSlides.length === 0) {
        return current
      }

      let slides = current.slides
      let anchorSlideId = targetSlideId

      for (const slide of importedSlides) {
        const result = insertPPTSlideAtTargetPlacement({
          placement: 'after',
          slide,
          slides,
          targetSlideId: anchorSlideId,
        })

        if (!result) {
          return current
        }

        slides = result.items
        anchorSlideId = slide.id
      }

      setLastDeckPPTXImportEffect(createPPTDeckPPTXImportEffect({
        importedSlides,
        mode: 'append',
        source,
      }))
      selectSlide(importedSlides[0].id)

      return {
        ...current,
        slides,
      }
    })

    return true
  }

