  function pastePPTTextParagraphSpacingSource(
    source: PPTTextParagraphSpacingImportSource,
  ) {
    const textElements = selectedElements.filter(
      (element): element is PPTTextElement =>
        isPPTTextElement(element) &&
        element.locked !== true &&
        element.visible !== false,
    )
    const lineHeight = source.spacing.lineHeight
    const spacingBefore = source.spacing.spacingBefore
    const spacingAfter = source.spacing.spacingAfter

    const effects = textElements.flatMap((element) =>
      getSlideEditTextParagraphSpacingPasteCommands({
        objectId: element.id,
        pasteValue: {
          fields: source.fields.flatMap((field): SlideEditTextParagraphSpacingPasteFieldValue[] => {
            const value = source.spacing[field]

            if (value === undefined) {
              return []
            }

            if (field === 'lineHeight') {
              return [{
                fieldId: 'lineHeightRatio',
                value,
              }]
            }

            return [{
              fieldId: field === 'spacingBefore'
                ? 'paragraphBefore'
                : 'paragraphAfter',
              value: {
                unit: 'px',
                value,
              },
            }]
          }),
          surface: 'text-paragraph-spacing',
          values: {
            ...(lineHeight === undefined ? {} : { lineHeightRatio: lineHeight }),
            ...(spacingBefore === undefined
              ? {}
              : {
                  paragraphBefore: {
                    unit: 'px',
                    value: spacingBefore,
                  },
                }),
            ...(spacingAfter === undefined
              ? {}
              : {
                  paragraphAfter: {
                    unit: 'px',
                    value: spacingAfter,
                  },
                }),
          },
        },
        slideId: activeSlide.id,
      }).map(getSlideEditTextParagraphSpacingCommandEffect))

    if (effects.length === 0) {
      return false
    }

    setLastTextParagraphSpacingEffect(effects[effects.length - 1])
    setLastTextParagraphSpacingImportEffect(
      createPPTTextParagraphSpacingImportEffect({
        effects,
        source,
      }),
    )
    commitDeck((current) =>
      updatePPTDeckSlide(current, activeSlide.id, (slide) => ({
        ...slide,
        elements: slide.elements.map((element) =>
          isPPTTextElement(element)
            ? applyPPTTextParagraphSpacingCommandEffectsToElement(
                element,
                effects.filter((effect) =>
                  effect.payload.objectId === element.id),
              )
            : element),
      })))

    return true
  }

