  function pastePPTTextAutoFitSource(source: PPTTextAutoFitImportSource) {
    const targets = selectedElements
      .filter((element): element is PPTTextElement =>
        isPPTTextElement(element) &&
          element.locked !== true &&
          element.visible !== false)
      .map((element) => ({
        bounds: pptGeometryToBounds(element.geometry),
        isHidden: element.visible === false,
        isLocked: element.locked === true,
        maxBounds: {
          h: PPT_SLIDE_HEIGHT,
          w: PPT_SLIDE_WIDTH,
          x: 0,
          y: 0,
        },
        measurement: getPPTTextAutoFitMeasurement(
          element,
          textOverflowById[element.id] === true,
        ),
        minSize: {
          h: 24,
          w: 24,
        },
        objectId: element.id,
      }))
    const pasteResult = getSlideEditTextAutoFitPasteCommandEffects({
      pasteValue: {
        handle: source.handle as SlideEditTextResizeHandle,
        mode: source.mode,
        sourceFields: {
          ...(source.fields.includes('handle') ? { handle: 'handle' } : {}),
          mode: 'mode',
        },
        surface: 'text-auto-fit',
      },
      slideId: activeSlide.id,
      targets,
    })
    const effects = pasteResult.effects

    if (effects.length === 0) {
      return false
    }

    const objectIds = effects.map((effect) => effect.payload.objectId)

    setLastTextAutoFitEffect(effects[effects.length - 1])
    setLastTextAutoFitImportEffect(createPPTTextAutoFitImportEffect({
      effects,
      source,
    }))
    commitDeck((current) =>
      updatePPTDeckSlide(current, activeSlide.id, (slide) => ({
        ...slide,
        elements: slide.elements.map((element) => {
          const effect = effects.find((effect) =>
            effect.payload.objectId === element.id)

          return effect && isPPTTextElement(element)
            ? applyPPTTextAutoFitCommandEffectToElement(element, effect)
            : element
        }),
      })))
    setTextOverflowById((current) => ({
      ...current,
      ...Object.fromEntries(objectIds.map((objectId) => [objectId, false])),
    }))

    return true
  }

  function pastePPTTextBodySource(source: PPTTextBodyImportSource) {
    const route = routePPTCanvasTextPasteReplace({
      getTarget: ({ selection: targetSelection }) =>
        getPPTTextPasteReplaceRouteTarget(targetSelection),
      selection,
      source: createPPTCanvasTextPasteSourceFromTextBodySource(source),
    })

    if (route.kind !== 'text-replace') {
      return false
    }

    const pasteValue = createPPTTextBodyPasteValue(source)
    const effects = route.intent.target.selection.flatMap((objectId) => {
      const effect = getSlideEditTextBodyPasteCommandEffect({
        normalizeBody: () => clonePPTTextBody(source.textBody),
        pasteValue,
        slideId: activeSlide.id,
        target: {
          isTextEditable: true,
          objectId,
        },
      })

      return effect ? [effect] : []
    })

    if (effects.length === 0) {
      return false
    }

    return pastePPTTextBodySourceToObjectIds({
      effects,
      source,
    })
  }

  function pastePPTTextBodySourceToObjectIds({
    effects,
    source,
  }: {
    effects: readonly PPTTextBodyReplaceHostCommandEffect[]
    source: PPTTextBodyImportSource
  }) {
    const objectIds = effects.map((effect) => effect.payload.objectId)

    setLastTextBodyImportEffect(createPPTTextBodyImportEffect({
      objectIds,
      source,
    }))

    commitDeck((current) =>
      updatePPTDeckSlide(current, activeSlide.id, (slide) => ({
        ...slide,
        elements: mapPPTElementsByIds(
          slide.elements,
          objectIds,
          (element) => {
            const effect = effects.find((effect) =>
              effect.payload.objectId === element.id)

            return effect && isPPTTextElement(element)
              ? {
                ...element,
                textBody: clonePPTTextBody(effect.payload.body),
              }
              : element
          },
        ),
      })))

    return true
  }

