function createPPTObjectAnimationImportCommandEffects({
  objectIds,
  slideId,
  source,
}: {
  objectIds: readonly string[]
  slideId: string
  source: PPTObjectAnimationImportSource
}): SlideEditObjectAnimationHostCommandEffect<string, string>[] {
  const effects: SlideEditObjectAnimationHostCommandEffect<string, string>[] = []

  for (const objectId of objectIds) {
    for (const field of source.fields) {
      const value = source.animation[field]

      if (value === undefined) {
        continue
      }

      effects.push(getSlideEditObjectAnimationUpdateCommandEffect(
        toSlideEditObjectAnimationCommand({
          elementId: objectId,
          field,
          slideId,
          value,
        }),
      ))
    }
  }

  return effects
}

function createPPTObjectStyleImportEffect({
  effect,
  source,
}: {
  effect: PPTStyleClipboardHostCommandEffect
  source: PPTObjectStyleImportSource
}): PPTObjectStyleImportEffect {
  const payload = effect.payload.id === 'paste-object-formatting'
    ? effect.payload
    : null
  const categories = payload
    ? uniquePPTCanvasValues(payload.categoryApplications.flatMap(
        (application) => application.appliedCategoryIds,
      )).join(' ')
    : ''
  const shadow = source.object.shadow

  return {
    categories,
    commandId: effect.payload.id,
    commandTargets: payload?.targetObjectIds.join(' ') ?? '',
    commandType: effect.type,
    fields: source.fields.join(' '),
    format: source.format,
    jsonLength: source.jsonLength,
    model: PPT_OBJECT_STYLE_IMPORT_MODEL,
    objectIds: payload?.categoryApplications
      .map((application) => application.objectId)
      .join(' ') ?? '',
    opacity: source.object.opacity === undefined
      ? ''
      : String(source.object.opacity),
    shadowAngle: shadow ? String(shadow.angle) : '',
    shadowBlur: shadow ? String(shadow.blur) : '',
    shadowColor: shadow?.color ?? '',
    shadowDistance: shadow ? String(shadow.distance) : '',
    shadowEnabled: shadow === undefined ? '' : String(shadow !== null),
    shadowOpacity: shadow ? String(shadow.opacity) : '',
  }
}

function createPPTObjectShadowImportEffect({
  effects,
  source,
}: {
  effects: readonly SlideEditObjectShadowHostCommandEffect<string, string>[]
  source: PPTObjectShadowImportSource
}): PPTObjectShadowImportEffect {
  const shadow = source.shadow === null
    ? null
    : normalizePPTElementShadow(source.shadow)

  return {
    angle: shadow ? String(shadow.angle) : '',
    blur: shadow ? String(shadow.blur) : '',
    color: shadow?.color ?? '',
    commandFields: effects.map((effect) => effect.payload.fieldId).join(' '),
    commandIds: effects.map((effect) => effect.payload.id).join(' '),
    commandTargets: effects.map((effect) => effect.payload.objectId).join(' '),
    commandTypes: effects.map((effect) => effect.type).join(' '),
    commandValues: effects.map((effect) => String(effect.payload.value)).join(' '),
    distance: shadow ? String(shadow.distance) : '',
    enabled: String(source.shadow !== null),
    fields: source.fields.join(' '),
    format: source.format,
    jsonLength: source.jsonLength,
    model: PPT_OBJECT_SHADOW_IMPORT_MODEL,
    objectIds: uniquePPTCanvasValues(
      effects.map((effect) => effect.payload.objectId),
    ).join(' '),
    opacity: shadow ? String(shadow.opacity) : '',
    slideId: effects[0]?.payload.slideId ?? '',
  }
}

function createPPTObjectShadowImportCommandEffects({
  objectIds,
  slideId,
  source,
}: {
  objectIds: readonly string[]
  slideId: string
  source: PPTObjectShadowImportSource
}): SlideEditObjectShadowHostCommandEffect<string, string>[] {
  const effects: SlideEditObjectShadowHostCommandEffect<string, string>[] = []
  const pasteValue = createSlideEditObjectShadowPasteValueFromPPTSource(source)

  for (const objectId of objectIds) {
    for (const command of getSlideEditObjectShadowPasteCommands({
      objectId,
      pasteValue,
      slideId,
    })) {
      effects.push(getSlideEditObjectShadowCommandEffect(command))
    }
  }

  return effects
}

function createSlideEditObjectShadowPasteValueFromPPTSource(
  source: PPTObjectShadowImportSource,
): SlideEditObjectShadowJSONPasteValue {
  const shadow = normalizeSlideEditObjectShadow(source.shadow)

  return {
    fields: source.fields.flatMap((field): SlideEditObjectShadowPasteFieldValue[] => {
      if (field === 'enabled') {
        return [{
          fieldId: 'enabled',
          value: source.shadow !== null,
        }]
      }

      if (source.shadow === null) {
        return []
      }

      return [{
        fieldId: field,
        value: shadow[field],
      }]
    }),
    shadow,
    surface: 'object-shadow',
  }
}

function applyPPTObjectShadowEffectsToElement(
  element: PPTElement,
  effects: readonly SlideEditObjectShadowHostCommandEffect<string, string>[],
): PPTElement {
  return effects.reduce((current, effect) => {
    const { fieldId, value } = effect.payload

    if (fieldId === 'enabled') {
      return {
        ...current,
        shadow: value === true ? getPPTElementShadow(current) : undefined,
      }
    }

    return {
      ...current,
      shadow: normalizePPTElementShadow({
        ...getPPTElementShadow(current),
        [fieldId]: value,
      }),
    }
  }, element)
}

