function createPPTObjectMetadataImportEffect({
  accessibilityEffects,
  hyperlinkEffects,
  renameEffects,
  source,
}: {
  accessibilityEffects: readonly SlideEditObjectAccessibilityHostCommandEffect<string, string>[]
  hyperlinkEffects: readonly SlideEditObjectHyperlinkHostCommandEffect<string, string>[]
  renameEffects: readonly PPTLayerPaneHostCommandEffect[]
  source: PPTObjectMetadataImportSource
}): PPTObjectMetadataImportEffect {
  const effects = [
    ...hyperlinkEffects,
    ...accessibilityEffects,
    ...renameEffects,
  ]
  const altText = source.metadata.altText

  return {
    altTextLength: typeof altText === 'string' ? altText.length : 0,
    altTextPresent: altText === undefined
      ? ''
      : String(typeof altText === 'string' && altText.length > 0),
    commandFields: effects.map((effect) =>
      getPPTObjectMetadataCommandField(effect)).join(' '),
    commandIds: effects.map((effect) => effect.payload.id).join(' '),
    commandTypes: effects.map((effect) => effect.type).join(' '),
    fields: source.fields.join(' '),
    format: source.format,
    hyperlinkUrl: source.metadata.hyperlinkUrl ?? '',
    jsonLength: source.jsonLength,
    model: PPT_OBJECT_METADATA_IMPORT_MODEL,
    name: source.metadata.name ?? '',
    objectIds: [...new Set(effects.flatMap((effect) =>
      getPPTObjectMetadataEffectObjectIds(effect)))]
      .join(' '),
    slideId: getPPTObjectMetadataEffectSlideId(effects[0]) ?? '',
  }
}

function createPPTObjectHyperlinkImportEffect({
  effects,
  source,
}: {
  effects: readonly SlideEditObjectHyperlinkHostCommandEffect<string, string>[]
  source: PPTObjectHyperlinkImportSource
}): PPTObjectHyperlinkImportEffect {
  return {
    commandFields: effects.map((effect) =>
      effect.payload.id === 'update-object-hyperlink'
        ? effect.payload.fieldId
        : '').join(' '),
    commandIds: effects.map((effect) => effect.payload.id).join(' '),
    commandTargets: effects.map((effect) => effect.payload.objectId).join(' '),
    commandTypes: effects.map((effect) => effect.type).join(' '),
    enabled: String(source.hyperlinkUrl !== null),
    fields: source.fields.join(' '),
    format: source.format,
    jsonLength: source.jsonLength,
    model: PPT_OBJECT_HYPERLINK_IMPORT_MODEL,
    objectIds: uniquePPTCanvasValues(
      effects.map((effect) => effect.payload.objectId),
    ).join(' '),
    slideId: effects[0]?.payload.slideId ?? '',
    url: source.hyperlinkUrl ?? '',
  }
}

function createPPTObjectHyperlinkSourceFromMediaRoute(
  route: Extract<
    PPTCanvasMediaObjectHyperlinkRoute,
    { kind: 'object-hyperlink' }
  >,
): PPTObjectHyperlinkImportSource {
  return {
    fields: ['url'],
    format: PPT_OBJECT_HYPERLINK_MEDIA_IMPORT_FORMAT,
    hyperlinkUrl: route.intent.url,
    jsonLength: route.intent.url.length,
  }
}

function createPPTObjectHyperlinkImportCommandEffects({
  objectIds,
  slideId,
  source,
}: {
  objectIds: readonly string[]
  slideId: string
  source: PPTObjectHyperlinkImportSource
}): SlideEditObjectHyperlinkHostCommandEffect<string, string>[] {
  return objectIds.flatMap((objectId) =>
    getSlideEditObjectHyperlinkPasteCommands({
      objectId,
      pasteValue: source.hyperlinkUrl
        ? {
            fields: [{
              fieldId: 'url',
              value: source.hyperlinkUrl,
            }],
            hyperlink: {
              target: 'new-context',
              title: '',
              url: source.hyperlinkUrl,
            },
            kind: 'set-hyperlink',
            surface: 'object-hyperlink',
          }
        : {
            hyperlink: {
              target: 'new-context',
              title: '',
              url: '',
            },
            kind: 'remove-hyperlink',
            surface: 'object-hyperlink',
          },
      slideId,
    }).map((command) => getSlideEditObjectHyperlinkCommandEffect(command)))
}

function createPPTObjectTransformImportEffect({
  objectIds,
  source,
}: {
  objectIds: readonly string[]
  source: PPTObjectTransformImportSource
}): PPTObjectTransformImportEffect {
  return {
    commandTargets: objectIds.join(' '),
    fields: source.fields.join(' '),
    format: source.format,
    h: source.transform.h === undefined ? '' : String(source.transform.h),
    jsonLength: source.jsonLength,
    model: PPT_OBJECT_TRANSFORM_IMPORT_MODEL,
    objectIds: objectIds.join(' '),
    rotation: source.transform.rotation === undefined
      ? ''
      : String(source.transform.rotation),
    w: source.transform.w === undefined ? '' : String(source.transform.w),
    x: source.transform.x === undefined ? '' : String(source.transform.x),
    y: source.transform.y === undefined ? '' : String(source.transform.y),
  }
}

function createPPTObjectTransformPasteValue(
  source: PPTObjectTransformImportSource,
): SlideEditObjectTransformJSONPasteValue {
  return {
    fields: source.fields,
    format: 'json',
    payloadLength: source.jsonLength,
    sourceFields: {},
    sourceType: source.format,
    surface: 'object-transform',
    transform: source.transform,
  }
}

function applyPPTObjectTransformEffectToElement(
  element: PPTElement,
  effect: PPTObjectTransformHostCommandEffect,
): PPTElement {
  const { transform } = effect.payload
  const bounds = {
    h: transform.h,
    w: transform.w,
    x: transform.x,
    y: transform.y,
  }
  const next = updatePPTElementBounds(element, bounds)

  return !effect.payload.fields.includes('rotation')
    ? next
    : {
        ...next,
        geometry: {
          ...next.geometry,
          rotation: normalizePPTCanvasRotationDegrees(
            transform.rotation,
          ),
        },
      }
}

function getPPTObjectMetadataCommandField(
  effect:
    | SlideEditObjectAccessibilityHostCommandEffect<string, string>
    | SlideEditObjectHyperlinkHostCommandEffect<string, string>
    | PPTLayerPaneHostCommandEffect,
) {
  switch (effect.payload.id) {
    case 'remove-object-alt-text':
    case 'remove-object-hyperlink':
      return ''
    case 'rename-object':
      return 'name'
    case 'update-object-accessibility':
    case 'update-object-hyperlink':
      return effect.payload.fieldId
    default:
      return ''
  }
}

function getPPTObjectMetadataEffectObjectIds(
  effect:
    | SlideEditObjectAccessibilityHostCommandEffect<string, string>
    | SlideEditObjectHyperlinkHostCommandEffect<string, string>
    | PPTLayerPaneHostCommandEffect,
) {
  switch (effect.payload.id) {
    case 'hide-objects':
    case 'lock-objects':
    case 'select-objects':
    case 'show-objects':
    case 'unlock-objects':
      return effect.payload.objectIds
    case 'rename-object':
    case 'reorder-object':
    case 'remove-object-alt-text':
    case 'remove-object-hyperlink':
    case 'update-object-accessibility':
    case 'update-object-hyperlink':
      return [effect.payload.objectId]
  }
}

function getPPTObjectMetadataEffectSlideId(
  effect:
    | SlideEditObjectAccessibilityHostCommandEffect<string, string>
    | SlideEditObjectHyperlinkHostCommandEffect<string, string>
    | PPTLayerPaneHostCommandEffect
    | undefined,
) {
  if (!effect) {
    return undefined
  }

  return 'slideId' in effect.payload
    ? effect.payload.slideId
    : effect.selection.slideId
}

function createPPTObjectMetadataHyperlinkEffects({
  objectIds,
  slideId,
  source,
}: {
  objectIds: readonly string[]
  slideId: string
  source: PPTObjectMetadataImportSource
}): SlideEditObjectHyperlinkHostCommandEffect<string, string>[] {
  if (source.metadata.hyperlinkUrl === undefined) {
    return []
  }

  return objectIds.map((objectId) =>
    getSlideEditObjectHyperlinkCommandEffect(
      source.metadata.hyperlinkUrl
        ? {
            fieldId: 'url',
            id: 'update-object-hyperlink',
            objectId,
            slideId,
            value: source.metadata.hyperlinkUrl,
          }
        : {
            id: 'remove-object-hyperlink',
            objectId,
            slideId,
          },
    ))
}

function createPPTObjectMetadataAccessibilityEffects({
  objectIds,
  slideId,
  source,
}: {
  objectIds: readonly string[]
  slideId: string
  source: PPTObjectMetadataImportSource
}): SlideEditObjectAccessibilityHostCommandEffect<string, string>[] {
  if (source.metadata.altText === undefined) {
    return []
  }

  return objectIds.map((objectId) =>
    getSlideEditObjectAccessibilityCommandEffect(
      source.metadata.altText
        ? {
            fieldId: 'altText',
            id: 'update-object-accessibility',
            objectId,
            slideId,
            value: source.metadata.altText,
          }
        : {
            id: 'remove-object-alt-text',
            objectId,
            slideId,
          },
    ))
}

function createPPTObjectMetadataRenameEffects({
  objectIds,
  slide,
  source,
}: {
  objectIds: readonly string[]
  slide: PPTSlide
  source: PPTObjectMetadataImportSource
}): PPTLayerPaneHostCommandEffect[] {
  if (source.metadata.name === undefined) {
    return []
  }

  const pasteValue = createSlideEditLayerPaneRenamePasteValueFromPPTSource(
    source,
  )
  const descriptor = createPPTLayerPaneDescriptor({
    activeObjectId: null,
    collapsedGroupIds: new Set(),
    selectedObjectIds: objectIds,
    slide,
  })

  return objectIds
    .map((objectId) =>
      getSlideEditLayerPaneRenamePasteCommandEffect({
        descriptor,
        objectId,
        pasteValue,
      }))
    .filter((effect): effect is PPTLayerPaneHostCommandEffect =>
      effect !== null)
}

function createSlideEditLayerPaneRenamePasteValueFromPPTSource(
  source: PPTObjectMetadataImportSource,
): SlideEditLayerPaneRenameJSONPasteValue {
  return {
    name: source.metadata.name ?? '',
    nameField: 'name',
    surface: 'object-layer-pane-rename',
  }
}

function applyPPTObjectHyperlinkCommandEffectToElement(
  element: PPTElement,
  effect: SlideEditObjectHyperlinkHostCommandEffect<string, string>,
): PPTElement {
  const hyperlink = effect.payload.id === 'update-object-hyperlink'
    ? normalizePPTElementHyperlink({ url: effect.payload.value ?? '' })
    : null

  return {
    ...element,
    hyperlink: hyperlink ?? undefined,
  }
}

function applyPPTObjectMetadataRenameCommandEffectToElement(
  element: PPTElement,
  effect: PPTLayerPaneHostCommandEffect,
): PPTElement {
  return effect.payload.id === 'rename-object'
    ? {
        ...element,
        name: effect.payload.name,
      }
    : element
}

function applyPPTObjectAccessibilityCommandEffectToElement(
  element: PPTElement,
  effect: SlideEditObjectAccessibilityHostCommandEffect<string, string>,
): PPTElement {
  const accessibility = effect.payload.id === 'update-object-accessibility'
    ? normalizePPTElementAccessibility({
        altText: typeof effect.payload.value === 'string'
          ? effect.payload.value
          : '',
      })
    : null

  return {
    ...element,
    accessibility: accessibility ?? undefined,
  }
}

function createPPTObjectStateImportEffect({
  effects,
  objectIds,
  source,
}: {
  effects: readonly PPTLayerPaneHostCommandEffect[]
  objectIds: readonly string[]
  source: PPTObjectStateImportSource
}): PPTObjectStateImportEffect {
  const lockEffects: PPTObjectStateLockHostCommandEffect[] =
    effects.filter(isPPTObjectStateLockEffect)
  const visibilityEffects: PPTObjectStateVisibilityHostCommandEffect[] =
    effects.filter(isPPTObjectStateVisibilityEffect)
  const lockTargets = uniquePPTCanvasValues(lockEffects.flatMap((effect) =>
    effect.payload.objectIds))
  const visibilityTargets = uniquePPTCanvasValues(
    visibilityEffects.flatMap((effect) => effect.payload.objectIds),
  )

  return {
    commandIds: effects.map((effect) => effect.payload.id).join(' '),
    commandTypes: effects.map((effect) => effect.type).join(' '),
    fields: source.fields.join(' '),
    format: source.format,
    jsonLength: source.jsonLength,
    locked: source.state.locked === undefined
      ? ''
      : String(source.state.locked),
    lockTargets: lockTargets.join(' '),
    model: PPT_OBJECT_STATE_IMPORT_MODEL,
    objectIds: objectIds.join(' '),
    slideId: effects[0]?.selection.slideId ?? '',
    visible: source.state.visible === undefined
      ? ''
      : String(source.state.visible),
    visibilityTargets: visibilityTargets.join(' '),
  }
}

function createPPTObjectStateImportCommandEffects({
  objectIds,
  slide,
  source,
}: {
  objectIds: readonly string[]
  slide: PPTSlide
  source: PPTObjectStateImportSource
}): PPTLayerPaneHostCommandEffect[] {
  const pasteValue = createSlideEditLayerPaneObjectStatePasteValueFromPPTSource(
    source,
  )

  if (!pasteValue) {
    return []
  }

  const descriptor = createPPTLayerPaneDescriptor({
    activeObjectId: null,
    collapsedGroupIds: new Set(),
    selectedObjectIds: objectIds,
    slide,
  })

  return objectIds.flatMap((objectId) =>
    getSlideEditLayerPaneObjectStatePasteCommandEffects({
      descriptor,
      objectId,
      pasteValue,
    }) ?? [])
}

function createSlideEditLayerPaneObjectStatePasteValueFromPPTSource(
  source: PPTObjectStateImportSource,
): SlideEditLayerPaneObjectStateJSONPasteValue | null {
  const lock = source.state.locked === undefined
    ? undefined
    : {
        isLocked: source.state.locked,
        sourceField: 'locked',
      }
  const visibility = source.state.visible === undefined
    ? undefined
    : {
        isHidden: !source.state.visible,
        sourceField: 'visible',
      }

  return lock || visibility
    ? {
        ...(lock ? { lock } : {}),
        surface: 'object-layer-pane-state',
        ...(visibility ? { visibility } : {}),
      }
    : null
}

function isPPTObjectStateLockEffect(
  effect: PPTLayerPaneHostCommandEffect,
): effect is PPTObjectStateLockHostCommandEffect {
  return effect.payload.id === 'lock-objects' ||
    effect.payload.id === 'unlock-objects'
}

function isPPTObjectStateVisibilityEffect(
  effect: PPTLayerPaneHostCommandEffect,
): effect is PPTObjectStateVisibilityHostCommandEffect {
  return effect.payload.id === 'hide-objects' ||
    effect.payload.id === 'show-objects'
}

function createPPTObjectLayerImportEffect({
  effect,
  source,
}: {
  effect: PPTLayerPaneHostCommandEffect
  source: PPTObjectLayerImportSource
}): PPTObjectLayerImportEffect {
  const payload = effect.payload

  return {
    commandId: payload.id,
    commandType: effect.type,
    fields: source.fields.join(' '),
    format: source.format,
    fromIndex: payload.id === 'reorder-object' ? payload.fromIndex : -1,
    jsonLength: source.jsonLength,
    model: PPT_OBJECT_LAYER_IMPORT_MODEL,
    objectId: payload.id === 'reorder-object' ? payload.objectId : '',
    position: source.layer.position ?? '',
    slideId: effect.selection.slideId,
    toIndex: payload.id === 'reorder-object' ? payload.toIndex : -1,
  }
}

function createPPTObjectLayerImportCommandEffect({
  objectId,
  slide,
  source,
}: {
  objectId: string
  slide: PPTSlide
  source: PPTObjectLayerImportSource
}): PPTLayerPaneHostCommandEffect | null {
  const pasteValue = createSlideEditLayerPaneObjectLayerPasteValueFromPPTSource(
    source,
  )

  if (!pasteValue) {
    return null
  }

  const descriptor = createPPTLayerPaneDescriptor({
    activeObjectId: objectId,
    collapsedGroupIds: new Set(),
    selectedObjectIds: [objectId],
    slide,
  })

  return getSlideEditLayerPaneObjectLayerPasteCommandEffect({
    descriptor,
    objectId,
    pasteValue,
  })
}

function createSlideEditLayerPaneObjectLayerPasteValueFromPPTSource(
  source: PPTObjectLayerImportSource,
): SlideEditLayerPaneObjectLayerJSONPasteValue | null {
  if (source.layer.toIndex !== undefined) {
    return {
      sourceField: 'toIndex',
      surface: 'object-layer-pane-order',
      toIndex: source.layer.toIndex,
      type: 'to-index',
    }
  }

  if (source.layer.position !== undefined) {
    return {
      position: source.layer.position,
      sourceField: 'position',
      surface: 'object-layer-pane-order',
      type: 'position',
    }
  }

  return null
}

