function formatPPTTextStyleImportInsetData(
  inset: Partial<NonNullable<PPTTextStyle['textInset']>>,
) {
  return (['top', 'right', 'bottom', 'left'] as const)
    .map((field) => inset[field] === undefined ? '' : String(inset[field]))
    .join(',')
}

