function applyPPTTextRunFormattingCommandEffectToElement(
  element: PPTTextElement,
  effect: PPTTextRunFormattingHostCommandEffect,
): PPTTextElement {
  const field = effect.payload.fieldId
  const value = getPPTTextRunFormattingCommandModelValue(effect)

  return {
    ...element,
    textBody: {
      paragraphs: element.textBody.paragraphs.map((paragraph) => ({
        ...paragraph,
        runs: paragraph.runs.map((run) => ({
          ...run,
          [field]: value,
        })),
      })),
    },
  }
}

function applyPPTTextClearFormattingCommandEffectToElement(
  element: PPTTextElement,
): PPTTextElement {
  const preservedTextStyle = getPPTTextElementStyle(element)

  return {
    ...element,
    style: {
      ...getDefaultPPTTextStyle(),
      textInset: getPPTTextElementInset(element),
      verticalAlign: preservedTextStyle.verticalAlign,
    },
    textBody: {
      paragraphs: element.textBody.paragraphs.map((paragraph) => ({
        runs: paragraph.runs.map((run) => ({
          text: run.text,
        })),
      })),
    },
  }
}

function getPPTTextRunFormattingCommandModelValue(
  effect: PPTTextRunFormattingHostCommandEffect,
) {
  const value = effect.payload.value

  switch (effect.payload.fieldId) {
    case 'bold':
    case 'italic':
    case 'strikethrough':
    case 'underline':
      return value === true ? true : undefined
    case 'color':
    case 'highlight':
      return typeof value === 'string' && value ? value : undefined
    case 'size':
      return typeof value === 'number' ? value : undefined
  }
}

function getPPTTextElementsRunCount(elements: readonly PPTTextElement[]) {
  return elements.reduce((count, element) =>
    count + element.textBody.paragraphs.reduce(
      (paragraphCount, paragraph) => paragraphCount + paragraph.runs.length,
      0,
    ), 0)
}

