function getPPTObjectFillOpacitySourceFromSlideEditJSONPasteValue(
  dataTransfer: DataTransfer,
): PPTObjectFillOpacityImportSource | null {
  const seen = new Set<string>()

  for (const customMimeType of [
    PPT_OBJECT_FILL_OPACITY_JSON_MIME_TYPE,
    SLIDE_EDIT_OBJECT_FILL_OPACITY_JSON_MIME_TYPE,
  ]) {
    for (const candidate of getPPTSlideEditJSONPasteCandidates({
      customMimeType,
      dataTransfer,
    })) {
      const json = getPPTImportJSONText(candidate.text) ?? candidate.text

      if (seen.has(json)) {
        continue
      }

      seen.add(json)

      const value = getPPTJSONValueFromText(json)

      if (
        !candidate.allowDirect &&
        isPPTRecord(value) &&
        shouldDeferPPTObjectFillOpacityToShapeStyle(value)
      ) {
        continue
      }

      const pasteValue = getSlideEditObjectFillOpacityJSONPasteValueFromText(
        json,
        {
          mode: candidate.allowDirect ? 'direct' : 'wrapped',
        },
      )

      if (pasteValue === null) {
        continue
      }

      return {
        fields: ['fillOpacity'],
        fillOpacity: normalizePPTFillOpacity(pasteValue.value),
        format: PPT_OBJECT_FILL_OPACITY_JSON_IMPORT_FORMAT,
        jsonLength: json.length,
      }
    }
  }

  return null
}

function getPPTObjectFillOpacitySourceFromText(
  text: string,
  allowDirect: boolean,
): PPTObjectFillOpacityImportSource | null {
  const json = getPPTImportJSONText(text)

  if (!json) {
    return null
  }

  try {
    return getPPTObjectFillOpacitySourceFromJSONValue(
      JSON.parse(json),
      json.length,
      allowDirect,
    )
  } catch {
    return null
  }
}

function getPPTObjectFillOpacitySourceFromJSONValue(
  value: unknown,
  jsonLength: number,
  allowDirect: boolean,
): PPTObjectFillOpacityImportSource | null {
  const fillOpacity = getPPTObjectFillOpacityFromJSONValue(
    getPPTObjectFillOpacityPayloadValue(value, allowDirect),
  )

  return fillOpacity === undefined
    ? null
    : {
        fields: ['fillOpacity'],
        fillOpacity,
        format: PPT_OBJECT_FILL_OPACITY_JSON_IMPORT_FORMAT,
        jsonLength,
      }
}

function getPPTObjectFillOpacityPayloadValue(
  value: unknown,
  allowDirect: boolean,
): unknown {
  if (!isPPTRecord(value)) {
    return allowDirect ? value : undefined
  }

  if (shouldDeferPPTObjectFillOpacityToShapeStyle(value)) {
    return undefined
  }

  if (value.objectFillOpacity !== undefined) {
    return value.objectFillOpacity
  }

  if (value.shapeFillOpacity !== undefined) {
    return value.shapeFillOpacity
  }

  if (value.fillOpacity !== undefined) {
    return value.fillOpacity
  }

  return allowDirect &&
    (
      value.opacity !== undefined ||
      value.value !== undefined ||
      value.amount !== undefined
    )
    ? value
    : undefined
}

function getPPTObjectFillOpacityFromJSONValue(
  value: unknown,
): number | undefined {
  const raw = isPPTRecord(value)
    ? value.fillOpacity ?? value.opacity ?? value.value ?? value.amount
    : value

  if (typeof raw === 'number') {
    return Number.isFinite(raw) ? normalizePPTFillOpacity(raw) : undefined
  }

  if (typeof raw !== 'string') {
    return undefined
  }

  const trimmed = raw.trim()

  if (!trimmed) {
    return undefined
  }

  const numberValue = Number(trimmed)

  return Number.isFinite(numberValue)
    ? normalizePPTFillOpacity(numberValue)
    : undefined
}

