type PPTTextRunFormattingImportField =
  | PPTTextRunBoldImportField
  | PPTTextRunItalicImportField
  | PPTTextRunStrikethroughImportField
  | PPTTextRunUnderlineImportField

function getPPTTextRunFormattingSourceFromSlideEditJSONPasteValue({
  dataTransfer,
  fieldId,
  pptJsonMimeType,
}: {
  dataTransfer: DataTransfer
  fieldId: SlideEditTextRunFormattingBooleanFieldId
  pptJsonMimeType: string
}): {
  fields: readonly PPTTextRunFormattingImportField[]
  jsonLength: number
  value: boolean
} | null {
  const seen = new Set<string>()

  for (const customMimeType of [
    pptJsonMimeType,
    getPPTTextRunFormattingJSONMimeType(fieldId),
  ]) {
    if (!customMimeType) {
      continue
    }

    for (const candidate of getPPTSlideEditJSONPasteCandidates({
      customMimeType,
      dataTransfer,
    })) {
      const json = getPPTImportJSONText(candidate.text) ?? candidate.text

      if (seen.has(json)) {
        continue
      }

      seen.add(json)

      const value = getSlideEditTextRunFormattingJSONPasteValueFromText(
        json,
        {
          mode: candidate.allowDirect ? 'direct' : 'wrapped',
          fieldId,
        },
      )

      if (value === null) {
        continue
      }

      const payload = getPPTTextRunFormattingPayloadEntry(
        fieldId,
        getPPTJSONValueFromText(json),
        candidate.allowDirect,
      )

      return {
        fields: payload?.fields ?? ['value'],
        jsonLength: json.length,
        value,
      }
    }
  }

  return null
}

function getPPTTextRunFormattingJSONMimeType(
  fieldId: SlideEditTextRunFormattingFieldId,
) {
  return SLIDE_EDIT_TEXT_RUN_FORMATTING_FIELDS.find((field) =>
    field.id === fieldId)?.jsonMimeType ?? ''
}

function getPPTTextRunFormattingPayloadEntry(
  fieldId: SlideEditTextRunFormattingBooleanFieldId,
  value: unknown,
  allowDirect: boolean,
): {
  fields: readonly PPTTextRunFormattingImportField[]
  value: unknown
} | null {
  switch (fieldId) {
    case 'bold':
      return getPPTTextRunBoldPayloadEntry(value, allowDirect)
    case 'italic':
      return getPPTTextRunItalicPayloadEntry(value, allowDirect)
    case 'strikethrough':
      return getPPTTextRunStrikethroughPayloadEntry(value, allowDirect)
    case 'underline':
      return getPPTTextRunUnderlinePayloadEntry(value, allowDirect)
  }
}

function getPPTTextRunUnderlineSourceFromText(
  text: string,
  allowDirect: boolean,
): PPTTextRunUnderlineImportSource | null {
  const json = getPPTImportJSONText(text)

  if (!json) {
    const rawText = text.trim()

    if (!allowDirect || !rawText) {
      return null
    }

    try {
      return getPPTTextRunUnderlineSourceFromJSONValue(
        JSON.parse(rawText),
        rawText.length,
        true,
      )
    } catch {
      return getPPTTextRunUnderlineSourceFromJSONValue(
        rawText,
        rawText.length,
        true,
      )
    }
  }

  try {
    return getPPTTextRunUnderlineSourceFromJSONValue(
      JSON.parse(json),
      json.length,
      allowDirect,
    )
  } catch {
    return null
  }
}

function getPPTTextRunUnderlineSourceFromJSONValue(
  value: unknown,
  jsonLength: number,
  allowDirect: boolean,
): PPTTextRunUnderlineImportSource | null {
  const payload = getPPTTextRunUnderlinePayloadEntry(value, allowDirect)

  if (!payload) {
    return null
  }

  const underline = getPPTTextRunUnderlineImportValueFromJSONValue(payload.value)

  return underline === undefined
    ? null
    : {
        fields: payload.fields,
        format: PPT_TEXT_RUN_UNDERLINE_JSON_IMPORT_FORMAT,
        jsonLength,
        underline,
      }
}

function getPPTTextRunUnderlinePayloadEntry(
  value: unknown,
  allowDirect: boolean,
): {
  fields: readonly PPTTextRunUnderlineImportField[]
  value: unknown
} | null {
  if (!isPPTRecord(value)) {
    return allowDirect
      ? {
          fields: ['value'],
          value,
        }
      : null
  }

  for (const field of [
    'textRunUnderline',
    'runUnderline',
    'underline',
    'value',
  ] as const) {
    if (value[field] !== undefined) {
      return {
        fields: [field],
        value: value[field],
      }
    }
  }

  return allowDirect
    ? {
        fields: ['value'],
        value,
      }
    : null
}

function getPPTTextRunUnderlineImportValueFromJSONValue(
  value: unknown,
): boolean | undefined {
  if (isPPTRecord(value)) {
    for (const field of [
      'value',
      'underline',
      'runUnderline',
      'textRunUnderline',
    ] as const) {
      if (value[field] !== undefined) {
        return getPPTTextRunUnderlineImportValueFromJSONValue(value[field])
      }
    }

    return undefined
  }

  if (typeof value === 'boolean') {
    return value
  }

  if (typeof value === 'number') {
    if (value === 1) {
      return true
    }

    if (value === 0) {
      return false
    }
  }

  if (typeof value !== 'string') {
    return undefined
  }

  switch (value.trim().replace(/[\s_]/g, '-').toLowerCase()) {
    case '1':
    case 'enabled':
    case 'on':
    case 'true':
    case 'underline':
    case 'underlined':
    case 'yes':
      return true
    case '0':
    case 'disabled':
    case 'false':
    case 'none':
    case 'no':
    case 'normal':
    case 'off':
    case 'regular':
    case 'upright':
      return false
    default:
      return undefined
  }
}

