function getPPTTextBodySourceFromText(
  text: string,
  allowDirect: boolean,
): PPTTextBodyImportSource | null {
  const json = getPPTImportJSONText(text)

  if (!json) {
    return null
  }

  try {
    return getPPTTextBodySourceFromJSONValue(
      JSON.parse(json),
      json.length,
      allowDirect,
    )
  } catch {
    return null
  }
}

function getPPTTextBodySourceFromJSONValue(
  value: unknown,
  jsonLength: number,
  allowDirect: boolean,
): PPTTextBodyImportSource | null {
  const payloadValue = getPPTTextBodyPayloadValue(value, allowDirect)

  if (typeof payloadValue === 'string') {
    const text = payloadValue.replace(/\r\n?/g, '\n')

    return text
      ? {
          format: PPT_TEXT_BODY_JSON_IMPORT_FORMAT,
          jsonLength,
          mode: 'plain-text',
          textBody: createPPTTextBody(text),
        }
      : null
  }

  const textBody = getPPTTextBodyFromJSONValue(payloadValue)

  return textBody
    ? {
        format: PPT_TEXT_BODY_JSON_IMPORT_FORMAT,
        jsonLength,
        mode: 'text-body',
        textBody,
      }
    : null
}

function createPPTTextBodySourceFromRichTextPasteSource(
  source: PPTRichTextPasteSource,
): PPTTextBodyImportSource {
  return {
    format: source.format ?? 'text-html-rich',
    jsonLength: source.text.length,
    mode: 'rich-text',
    textBody: source.textBody,
  }
}

function createPPTTextBodySourceFromPlainTextPaste(
  text: string,
): PPTTextBodyImportSource {
  const normalizedText = text.replace(/\r\n?/g, '\n')

  return {
    format: 'text-plain',
    jsonLength: normalizedText.length,
    mode: 'plain-text',
    textBody: createPPTTextBody(normalizedText),
  }
}

function getPPTTextBodyPayloadValue(
  value: unknown,
  allowDirect: boolean,
): unknown {
  if (!isPPTRecord(value)) {
    return allowDirect ? value : null
  }

  if (isPPTRecord(value.textBody) || typeof value.textBody === 'string') {
    return value.textBody
  }

  if (isPPTRecord(value.body) || typeof value.body === 'string') {
    return value.body
  }

  if (isPPTRecord(value.content) || typeof value.content === 'string') {
    return value.content
  }

  if (hasPPTTextBodyStandalonePayloadFields(value)) {
    return value
  }

  if (typeof value.text === 'string') {
    return value.text
  }

  if (typeof value.plainText === 'string') {
    return value.plainText
  }

  return allowDirect ? value : null
}

function hasPPTTextBodyStandalonePayloadFields(
  value: Record<string, unknown>,
): boolean {
  return Array.isArray(value.paragraphs)
}

