function getPPTTextFrameInsetSourceFromSlideEditJSONPasteValue(
  dataTransfer: DataTransfer,
): PPTTextFrameInsetImportSource | null {
  const seen = new Set<string>()

  for (const customMimeType of [
    PPT_TEXT_FRAME_INSET_JSON_MIME_TYPE,
    SLIDE_EDIT_TEXT_FRAME_INSET_JSON_MIME_TYPE,
  ]) {
    for (const candidate of getPPTSlideEditJSONPasteCandidates({
      customMimeType,
      dataTransfer,
    })) {
      const json = getPPTImportJSONText(candidate.text) ?? candidate.text

      if (seen.has(json)) {
        continue
      }

      seen.add(json)

      const pasteValue = getSlideEditTextFrameInsetJSONPasteValueFromText(
        json,
        {
          mode: candidate.allowDirect ? 'direct' : 'wrapped',
        },
      )

      if (pasteValue === null) {
        continue
      }

      return createPPTTextFrameInsetSourceFromSlideEditJSONPasteValue(
        pasteValue,
        json.length,
      )
    }
  }

  return null
}

function createPPTTextFrameInsetSourceFromSlideEditJSONPasteValue(
  pasteValue: NonNullable<ReturnType<typeof getSlideEditTextFrameInsetJSONPasteValueFromText>>,
  jsonLength: number,
): PPTTextFrameInsetImportSource | null {
  const fields: PPTTextFrameInsetImportField[] = []
  const inset: Partial<PPTTextInset> = {}

  for (const field of pasteValue.fields) {
    fields.push(field.fieldId)
    inset[field.fieldId] = normalizePPTTextInset(field.value)
  }

  return fields.length === 0
    ? null
    : {
        fields,
        format: PPT_TEXT_FRAME_INSET_JSON_IMPORT_FORMAT,
        inset,
        jsonLength,
      }
}

function getPPTTextFrameInsetSourceFromText(
  text: string,
  allowDirect: boolean,
): PPTTextFrameInsetImportSource | null {
  const json = getPPTImportJSONText(text)

  if (!json) {
    return null
  }

  try {
    return getPPTTextFrameInsetSourceFromJSONValue(
      JSON.parse(json),
      json.length,
      allowDirect,
    )
  } catch {
    return null
  }
}

function getPPTTextFrameInsetSourceFromJSONValue(
  value: unknown,
  jsonLength: number,
  allowDirect: boolean,
): PPTTextFrameInsetImportSource | null {
  const payloadValue = getPPTTextFrameInsetPayloadValue(value, allowDirect)
  const fields = ['top', 'right', 'bottom', 'left'] as const
  const inset: Partial<PPTTextInset> = {}

  if (typeof payloadValue === 'number') {
    const insetValue = getPPTTextFrameInsetFieldValueFromJSONValue(payloadValue)

    if (insetValue === undefined) {
      return null
    }

    fields.forEach((field) => {
      inset[field] = insetValue
    })

    return {
      fields,
      format: PPT_TEXT_FRAME_INSET_JSON_IMPORT_FORMAT,
      inset,
      jsonLength,
    }
  }

  if (Array.isArray(payloadValue)) {
    fields.forEach((field, index) => {
      const fieldValue = getPPTTextFrameInsetFieldValueFromJSONValue(
        payloadValue[index],
      )

      if (fieldValue !== undefined) {
        inset[field] = fieldValue
      }
    })

    const sourceFields = fields.filter((field) => inset[field] !== undefined)

    return sourceFields.length > 0
      ? {
          fields: sourceFields,
          format: PPT_TEXT_FRAME_INSET_JSON_IMPORT_FORMAT,
          inset,
          jsonLength,
        }
      : null
  }

  if (!isPPTRecord(payloadValue)) {
    return null
  }

  fields.forEach((field) => {
    const fieldValue = getPPTTextFrameInsetFieldValueFromJSONValue(
      payloadValue[field],
    )

    if (fieldValue !== undefined) {
      inset[field] = fieldValue
    }
  })

  const sourceFields = fields.filter((field) => inset[field] !== undefined)

  return sourceFields.length > 0
    ? {
        fields: sourceFields,
        format: PPT_TEXT_FRAME_INSET_JSON_IMPORT_FORMAT,
        inset,
        jsonLength,
      }
    : null
}

function getPPTTextFrameInsetPayloadValue(
  value: unknown,
  allowDirect: boolean,
): unknown {
  if (!isPPTRecord(value)) {
    return allowDirect ? value : null
  }

  if (
    isPPTRecord(value.textFrameInset) ||
    Array.isArray(value.textFrameInset) ||
    typeof value.textFrameInset === 'number'
  ) {
    return value.textFrameInset
  }

  if (
    isPPTRecord(value.textInset) ||
    Array.isArray(value.textInset) ||
    typeof value.textInset === 'number'
  ) {
    return value.textInset
  }

  if (
    isPPTRecord(value.textPadding) ||
    Array.isArray(value.textPadding) ||
    typeof value.textPadding === 'number'
  ) {
    return value.textPadding
  }

  if (
    isPPTRecord(value.inset) ||
    Array.isArray(value.inset) ||
    typeof value.inset === 'number'
  ) {
    return value.inset
  }

  if (
    isPPTRecord(value.padding) ||
    Array.isArray(value.padding) ||
    typeof value.padding === 'number'
  ) {
    return value.padding
  }

  if (allowDirect && (
    typeof value.top === 'number' ||
    typeof value.right === 'number' ||
    typeof value.bottom === 'number' ||
    typeof value.left === 'number'
  )) {
    return value
  }

  return allowDirect ? value : null
}

function getPPTTextFrameInsetFieldValueFromJSONValue(
  value: unknown,
): number | undefined {
  return typeof value === 'number' && Number.isFinite(value)
    ? normalizePPTTextInset(value)
    : undefined
}

function getPPTTextBodyFromJSONValue(value: unknown): PPTTextBody | null {
  const parsed = PPTTextBodySchema.safeParse(value)

  if (!parsed.success) {
    return null
  }

  return normalizePPTImportedTextBody(parsed.data)
}

function normalizePPTImportedTextBody(body: PPTTextBody): PPTTextBody {
  const paragraphs = body.paragraphs.length > 0
    ? body.paragraphs
    : [{ runs: [{ text: '' }] }]

  return {
    paragraphs: paragraphs.map((paragraph) => {
      const paragraphWithoutLevel = { ...paragraph }
      delete paragraphWithoutLevel.level
      const level = getPPTParagraphListLevelModelValue(
        getPPTParagraphListLevel(paragraph),
      )

      return {
        ...paragraphWithoutLevel,
        ...(level === undefined ? {} : { level }),
        runs: paragraph.runs.length > 0
          ? paragraph.runs.map((run) => ({ ...run }))
          : [{ text: '' }],
      }
    }),
  }
}

